    p.x += dt * kx * (noite ? Math.sin(p.fase * 0.9) * 9 * s : -(3.5 + p.vel * 3)) - desloc;
    p.y += dt * kx * (noite ? Math.cos(p.fase * 0.7) * 6 * s : (2.2 + p.vel * 2.4));
    if (p.x < -margem) { p.x += g.cw + margem * 2; p.y = g.ch * (0.18 + Math.random() * 0.62); }
    if (p.x > g.cw + margem) { p.x -= g.cw + margem * 2; p.y = g.ch * (0.18 + Math.random() * 0.62); }
    if (p.y > g.ch * 0.88) p.y = g.ch * 0.18 + (p.y - g.ch * 0.88);
    if (p.y < g.ch * 0.12) p.y = g.ch * 0.12;
