// ---------- MATA ATLÂNTICA ----------
// THE LIGHT SHAFT, BAKED. A forest is a dark room with one window in it, and the window is
// the far end of the trail. It is drawn as an APERTURE and never as a hole cut in the
// foliage: the trees tile in world space and the shaft is fixed to the screen, and wave 20
// paid for the rule that anything whose SHAPE reads the screen while its content tiles in
// the world will pump as it scrolls. A wash laid over the top of the mid distance has no
// shape of its own to pump — it is the air between you and the trees, lit — and it costs one
// `drawImage` a frame because it is baked on the same keys the sky is.
let mataLuzCv: HTMLCanvasElement | null = null, mataLuzKey = "";
function mataLuz(h, P) {
  const key = W + "," + GROUND + "," + Math.round(h * 48) + "," + horaKey() + "," + ritmoQ();
  if (mataLuzCv && mataLuzKey === key) return mataLuzCv;
  if (!mataLuzCv) mataLuzCv = document.createElement("canvas");
  mataLuzCv.width = W; mataLuzCv.height = GROUND + 8;
  mataLuzKey = key;
  const g = mataLuzCv.getContext("2d")!;
  const alt = GROUND + 8;
  const img = g.createImageData(W, alt);
  const d = img.data, c = P.faixaA;
  // TRIED AND MEASURED AND CUT BY FOUR FIFTHS: the first cut opened at GROUND·0.28, spread to
  // 0.39·W and peaked at alpha 0.86, and the frame came out 122 against a board panel of 53 —
  // a forest with a searchlight in it. A shaft is a thing you notice at the end of the path,
  // not the light the picture is lit by; the picture is lit by the hour like everywhere else.
  const topo = GROUND * 0.44, pe = GROUND + 4, eixo = W * 0.46;
  for (let y = 0; y < alt; y++) {
    if (y < topo) continue;
    const t = Math.min(1, (y - topo) / (pe - topo));
    // it opens as it comes down — a gap in the canopy overhead, a pool of light on the path —
    // and it dies just past the ground line, because the trail at your feet is in shade
    const meia = W * (0.045 + 0.23 * Math.pow(t, 0.85));
    // AND ITS PEAK IS HALF WAY UP, NOT AT THE GROUND LINE. Measured: with the peak at t 0.74
    // the fourth fifth of the frame came out 90 against the panel's 48, because that is where
    // the pool and the trail land on top of each other. The board's corridor is brightest
    // across its MIDDLE (62, 57) and its two bottom fifths are the darkest thing in it.
    const vert = Math.pow(Math.min(1, t / 0.55), 1.2) * (1 - 0.92 * Math.max(0, (t - 0.55) / 0.45));
    if (vert <= 0) continue;
    for (let x = 0; x < W; x++) {
      const u = (x - eixo) / meia;
      const f = 1 - u * u;                       // a parabola, so the pool has no edge to it
      if (f <= 0) continue;
      const a = Math.round(255 * Math.min(0.40, f * f * vert * 0.42));
      if (a <= 0) continue;
      const i = (y * W + x) * 4;
      d[i] = c[0]; d[i + 1] = c[1]; d[i + 2] = c[2]; d[i + 3] = a;
    }
  }
  g.putImageData(img, 0, 0);
  return mataLuzCv;
}
// a trunk drawn as a column of bark: the same per-row span the street's proscenium uses,
// with a lit right edge because there is one sun in this file and it is up and to the right
function troncoCol(x, larg, y0, y1, K, C, L2) {
  cx.fillStyle = K; cx.fillRect(x - 1, y0, larg + 2, y1 - y0);
  cx.fillStyle = C; cx.fillRect(x, y0, larg, y1 - y0);
  cx.fillStyle = L2; cx.fillRect(x + larg - 1, y0, 1, y1 - y0);
}

